      "id": "r2",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "जातः कूर्मः स एकः पृथुभुवनभरायार्पितं येन पृष्ठं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "",
          "end": "join"
        },
        {
          "n": 3,
          "text": "श्लाघ्यं जन्म ध्रुवस्य भ्रमति नियमितं यत्र तेजस्विचक्रम् ।",
          "end": "line"
        },
        {
          "n": 4,
          "text": "संजातव्यर्थपक्षाः परहितकरणे नोपरिष्टान्न चाधो",
          "end": "line"
        },
        {
          "n": 5,
          "text": "ब्रह्माण्डोदुम्बरान्तर्मशकवदपरे जन्तवो जातनष्टाः ॥ १८ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "तुङ्गं वेश्म सुताः सतामभिमताः संख्यातिगाः संपदः",
          "end": "line"
        },
        {
          "n": 2,
          "text": "कल्याणी दयिता वयश्च नवमित्यज्ञानमूढो जनः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "मत्वा विश्वमनश्वरं निविशते संसारकारागृहे",
          "end": "line"
        },
        {
          "n": 4,
          "text": "संदृश्य क्षणभङ्गुरं तदखिलं धन्यस्तु संन्यस्यति ॥ १९ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "ददतु ददतु गालीर्गालिमन्तो भवन्तो",
          "end": "line"
        },
        {
          "n": 2,
          "text": "वयमपि तदभावाद्गालिदानेसमर्थाः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "जगति विदितमेतद्दीयते विद्यमानं",
          "end": "line"
        },
        {
          "n": 4,
          "text": "न हि शशकविषाणं कोपि कस्मै ददाति ॥ २० ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "दूरादर्थं घटयति नवं दूरतश्चापशब्दं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "त्यक्त्वा भूयो भवति निरतः सत्सभारञ्जनेषु ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "मन्दं मन्दं रचयति पदं लोकचित्तानुवृत्त्या",
          "end": "line"
        },
        {
          "n": 4,
          "text": "",
          "end": "join"
        },
        {
          "n": 5,
          "text": "कामं मन्त्री कविरिव सदा खेदभारैरमुक्तः ॥ २१ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "न भिक्षा दुष्प्रापा पथि मम महारामरचिते",
          "end": "line"
        },
        {
          "n": 2,
          "text": "फलैः संपूर्णा भूर्द्विपमृगसुचर्मापि वसनम् ।",
          "end": "line"
        }
      ],
      "uncertain": false,
      "note": null
    },
